#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int maxStability(int n, std::vector<std::vector<int>>& edges, int k) {
        int max_w = 0;
        for (const auto& e : edges) max_w = std::max(max_w, e[2]);

        auto check = [&](int S) {
            std::vector<int> parent(n);
            std::iota(parent.begin(), parent.end(), 0);

            auto find = [&](auto& self, int x) -> int {
                return parent[x] == x ? x : parent[x] = self(self, parent[x]);
            };

            auto unite = [&](int x, int y) {
                int rx = find(find, x), ry = find(find, y);
                if (rx != ry) {
                    parent[rx] = ry;
                    return true;
                }
                return false;
            };

            int components = n;
            for (const auto& e : edges) {
                int u = e[0], v = e[1], w = e[2];
                if (w >= S) {
                    if (unite(u, v)) components--;
                }
            }

            int upgrades_used = 0;
            for (const auto& e : edges) {
                int u = e[0], v = e[1], w = e[2];
                if (w < S && 2 * w >= S) {
                    if (unite(u, v)) {
                        upgrades_used++;
                        components--;
                        if (upgrades_used > k) return false;
                    }
                }
            }

            return components == 1 && upgrades_used <= k;
        };

        int low = 1, high = 2 * max_w, ans = 0;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxStability(int n, int[][] edges, int k) {
        int maxW = 0;
        for (int[] e : edges) maxW = Math.max(maxW, e[2]);

        int low = 1, high = 2 * maxW, ans = 0;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(n, edges, k, mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }

    private boolean check(int n, int[][] edges, int k, int S) {
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        int components = n;
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            if (w >= S) {
                if (union(parent, u, v)) components--;
            }
        }

        int upgradesUsed = 0;
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            if (w < S && 2 * w >= S) {
                if (union(parent, u, v)) {
                    upgradesUsed++;
                    components--;
                    if (upgradesUsed > k) return false;
                }
            }
        }

        return components == 1 && upgradesUsed <= k;
    }

    private int find(int[] parent, int x) {
        if (parent[x] != x) parent[x] = find(parent, parent[x]);
        return parent[x];
    }

    private boolean union(int[] parent, int x, int y) {
        int rx = find(parent, x), ry = find(parent, y);
        if (rx != ry) {
            parent[rx] = ry;
            return true;
        }
        return false;
    }
}

