var maxStability = function(n, edges, k) {
    let maxW = 0;
    for (const [u, v, w] of edges) {
        if (w > maxW) maxW = w;
    }

    const check = (S) => {
        const parent = new Int32Array(n);
        for (let i = 0; i < n; i++) parent[i] = i;

        const find = (x) => {
            if (parent[x] !== x) parent[x] = find(parent[x]);
            return parent[x];
        };

        const union = (x, y) => {
            const rx = find(x), ry = find(y);
            if (rx !== ry) {
                parent[rx] = ry;
                return true;
            }
            return false;
        };

        let components = n;
        for (const [u, v, w] of edges) {
            if (w >= S) {
                if (union(u, v)) components--;
            }
        }

        let upgradesUsed = 0;
        for (const [u, v, w] of edges) {
            if (w < S && 2 * w >= S) {
                if (union(u, v)) {
                    upgradesUsed++;
                    components--;
                    if (upgradesUsed > k) return false;
                }
            }
        }

        return components === 1 && upgradesUsed <= k;
    };

    let low = 1, high = 2 * maxW, ans = 0;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (check(mid)) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return ans;
};
